/**
 * Sprint 32R — Decision Support Response QA / User-Visible Dry Run Plan: fixtures.
 *
 * Scenario descriptors used by
 * `tests/playbook-engine-conversation-decision-support-response-qa-dry-run-plan.test.mjs`. Each entry
 * documents one behavior this sprint must exhibit — some carry a `sourceCase` (a minimal
 * `{ caseId, routeKind }` shape, exactly what a Sprint 31R integration case assessment already
 * carries) that the test file feeds through the actual pipeline; others (e.g. "attempt to enable X
 * blocked", "gate Y") describe a config/gate-level invariant the test file checks directly, and use
 * neutral placeholders for the fields that do not apply.
 *
 * This fixture never imports from `src/`, and is never imported by production code — it exists only
 * for this sprint's own test suite.
 */

export type DecisionSupportResponseQaDryRunPlanFixtureSourceCase = {
  caseId: string;
  routeKind: "clarification_gated_decision_support" | "existing_route_preserved" | "unsupported_preserved" | "shadow_only";
};

export type DecisionSupportResponseQaDryRunPlanFixtureCase = {
  id: string;
  scenario: string;
  responseKind: string;
  expectedQaStatus: string;
  expectedRiskLevel: string;
  expectedSafeForResponseDraftHarness: boolean;
  expectedSafeForUserVisibleDryRunNow: boolean;
  expectedSafeForProduction: boolean;
  expectedDirectDecisionBlocked: boolean;
  expectedSideEffectsZero: boolean;
  expectedLeaksZero: boolean;
  notes: string;
  /** Present only for scenarios that build/assess a real synthetic draft. */
  sourceCase?: DecisionSupportResponseQaDryRunPlanFixtureSourceCase;
  /** Present only for the thirteen "attempt to enable X blocked" config scenarios. */
  configOverrideField?:
    | "allowUserVisibleDryRun"
    | "allowProductionWiring"
    | "allowRouterChange"
    | "allowComposerChange"
    | "allowEndpointChange"
    | "allowFeatureFlag"
    | "allowRealPersistence"
    | "allowDbWrite"
    | "allowSupabaseWrite"
    | "allowExternalCalls"
    | "allowActionExecution"
    | "allowTaskCreation"
    | "allowEmailDraftCreation";
  /** Present only for the fourteen gate-evaluation scenarios. */
  gateType?: string;
};

